import re
import sys
import zipfile
import xml.etree.ElementTree as ET
from collections import Counter

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
MAIN_NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'

def col_to_idx(ref):
    letters = ''.join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + ord(ch.upper()) - 64
    return idx - 1

def shared_strings(z):
    if 'xl/sharedStrings.xml' not in z.namelist():
        return []
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    values = []
    for si in root.findall('m:si', NS):
        parts = []
        for t in si.iter('{%s}t' % MAIN_NS):
            parts.append(t.text or '')
        values.append(''.join(parts))
    return values

def xlsx_rows(path):
    with zipfile.ZipFile(path) as z:
        strings = shared_strings(z)
        sheet_name = 'xl/worksheets/sheet1.xml'
        root = ET.fromstring(z.read(sheet_name))
        rows = []
        for row in root.findall('.//m:sheetData/m:row', NS):
            vals = []
            for c in row.findall('m:c', NS):
                idx = col_to_idx(c.attrib['r'])
                while len(vals) <= idx:
                    vals.append(None)
                cell_type = c.attrib.get('t')
                if cell_type == 'inlineStr':
                    texts = [t.text or '' for t in c.iter('{%s}t' % MAIN_NS)]
                    val = ''.join(texts)
                else:
                    v = c.find('m:v', NS)
                    val = None if v is None else v.text
                    if cell_type == 's' and val is not None:
                        val = strings[int(val)]
                vals[idx] = val
            rows.append(vals)
        return rows

def cell(row, idx):
    return row[idx] if idx < len(row) else None

def split_genes(value):
    if value is None:
        return []
    return [g.strip() for g in re.split(r'[;,]', str(value)) if g.strip()]

variant_path, genes_path, counts_path, top_path = sys.argv[1:5]
chip_rows = xlsx_rows(genes_path)
chip_genes = set()
for row in chip_rows:
    if row and row[0] is not None and str(row[0]).strip():
        chip_genes.add(str(row[0]).strip())
if not chip_genes:
    raise SystemExit('No CHIP genes found')

rows = xlsx_rows(variant_path)
header_i = None
for i, row in enumerate(rows):
    labels = [str(x).strip() if x is not None else '' for x in row]
    if 'Zygosity' in labels and 'Gene Names' in labels:
        header_i = i
        header = labels
        break
if header_i is None:
    raise SystemExit('Variant header not found')
zyg_idx = header.index('Zygosity')
gene_idx = header.index('Gene Names')

counts = Counter()
for row in rows[header_i + 1:]:
    zyg = cell(row, zyg_idx)
    if zyg is None:
        continue
    zyg_label = str(zyg).strip()
    if not zyg_label or zyg_label.lower() in ('reference', 'no call', 'nocall', 'not called'):
        continue
    for gene in split_genes(cell(row, gene_idx)):
        if gene in chip_genes:
            counts[gene] += 1
if not counts:
    raise SystemExit('No non-reference variants in CHIP genes found')

ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
with open(counts_path, 'w') as out:
    out.write('gene\\tnon_reference_variant_count\\n')
    for gene, count in ranked:
        out.write('%s\\t%d\\n' % (gene, count))
with open(top_path, 'w') as out:
    out.write(ranked[0][0] + '\\n')
'''
print(base64.b64encode(script.encode()).decode())
